def cifrar_telefonos(apps, schema_editor):
    """Los teléfonos ya guardados se leen en claro y se vuelven a guardar cifrados."""
    Usuario = apps.get_model("usuarios", "Usuario")
    for num, telefono in Usuario.objects.exclude(telefono=None).values_list("num", "telefono"):
        if telefono:
            Usuario.objects.filter(pk=num).update(telefono=telefono)


